function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

const log = debounce((word) => console.log(word), 30);

log("a");
setTimeout(() => log("b"), 10);
setTimeout(() => log("c"), 60);
setTimeout(() => log("d"), 70);
